import scipy.integrate as integrate

def compute_moment(dist : rv_continuous, n: int) -> float:
    def moment_integrand(x):
        return x**n * dist.pdf(x)

    moment, _ = integrate.quad(moment_integrand, -np.inf, np.inf)
    return moment

