from sympy import Function, Max, Min
import sympy

def custom_parse_mathematica(expr : str) -> sympy.Expr:
    # Parse the Mathematica expression into a SymPy expression
    sympy_expr = parse_mathematica(expr)

    # Define the new function F
    F = Function('F')

    # Replace every occurrence of F with the new function
    def replace_F(expr):
        if expr.func == F:
            args = expr.args
            if not args:
                return 1  # F[] should return 1
            min_arg = min(args)
            max_arg = max(args)
            return Max(min_arg, max_arg) * Min(min_arg, max_arg)
        else:
            return expr.replace(F, replace_F)

    modified_expr = replace_F(sympy_expr)

    return modified_expr

